```c
int rb_delete(rbtree_t *t, const char *key) {
    rb_node_t *z = t->root;
    while (z != NULL) {
        int cmp = strcmp(key, z->key);
        if (cmp == 0) break;
        z = (cmp < 0) ? z->left : z->right;
    }
    if (z == NULL) {
        return -1;
    }

    rb_node_t *y = z;
    rb_color_t y_original_color = y->color;
    rb_node_t *x;
    rb_node_t *x_parent;

    if (z->left == NULL) {
        x = z->right;
        x_parent = z->parent;
